// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- OpenNext's documented generated entry exists only after a build.
// @ts-ignore Generated by the OpenNext build; absent in a clean checkout.
import handler from "../.open-next/worker.js";
import { publicDemoGuard } from "./public-guard";
import { RECORDING_HEADER, validRecordingId } from "../lib/recording";

export { DrawCoverState } from "./state";

const worker = {
  async fetch(request: Request, env: CloudflareEnv, ctx: unknown) {
    const path = new URL(request.url).pathname;
    const traced = path === "/api/drawcover" || path.startsWith("/api/drawcover/");
    const started = Date.now();
    const suppliedId = request.headers.get("X-DrawCover-Request-Id");
    const requestId = validRecordingId(suppliedId) ? suppliedId : crypto.randomUUID();
    const receipt = request.headers.get(RECORDING_HEADER) ?? new URL(request.url).searchParams.get("id");
    const recording = traced && validRecordingId(receipt) ? Array.from(new Uint8Array(
      await crypto.subtle.digest("SHA-256", new TextEncoder().encode(receipt)),
    ), byte => byte.toString(16).padStart(2, "0")).join("").slice(0, 12) : undefined;
    if (traced) console.info("[DrawCover request]", JSON.stringify({
      requestId, recording, path, method: request.method, outcome: "started",
    }));
    const finish = (response: Response) => {
      if (traced) {
        response.headers.set("X-DrawCover-Request-Id", requestId);
        console.info("[DrawCover request]", JSON.stringify({
          requestId, recording, path, method: request.method, status: response.status,
          elapsedMs: Date.now() - started, outcome: "response-created",
        }));
      }
      return response;
    };
    try {
      const blocked = await publicDemoGuard(request, env);
      if (blocked) return finish(blocked);
    } catch {
      console.error("[DrawCover] Public request protection failed.");
      return finish(Response.json(
        { message: "Public request protection is unavailable. Please try again later." },
        { status: 503, headers: { "Cache-Control": "no-store" } },
      ));
    }
    return finish(await handler.fetch(request, env, ctx));
  },
};

export default worker;
